param()
function Replace-Method([string]$text,[string]$needle,[string]$replacement){$start=$text.IndexOf($needle);if($start -lt 0){throw "Missing method $needle"};$open=$text.IndexOf('{',$start);$depth=1;$end=$open+1;while($depth -gt 0){if($text[$end] -eq '{'){$depth++};if($text[$end] -eq '}'){$depth--};$end++};return $text.Substring(0,$start)+$replacement+$text.Substring($end)}
$root='F:\MeetoMXH\app\src\main\java\com\example\meetomxh'
$path="$root/ProfileActivity.java";$text=[IO.File]::ReadAllText($path);$text=$text.Replace('import com.google.firebase.firestore.FirebaseFirestore;','import com.example.meetomxh.supabase.*;').Replace('    private FirebaseFirestore db;','').Replace('        db = FirebaseFirestore.getInstance();','');$body=@"
private void loadUserProfile() {
 ProfileClient.get(targetUid,new Api.Callback<User>(){public void success(User user){if(isFinishing())return;targetProfileExists=true;binding.tvFullName.setText(user.getFullName());binding.tvBio.setText(user.getBio());binding.tvGender.setText(user.getGender());binding.tvDob.setText(user.getDateOfBirth());binding.tvGender.setVisibility(user.getGender()==null?View.GONE:View.VISIBLE);binding.tvDob.setVisibility(user.getDateOfBirth()==null?View.GONE:View.VISIBLE);Glide.with(ProfileActivity.this).load(user.getAvatarUrl()).placeholder(R.drawable.ic_home).into(binding.imgAvatar);Glide.with(ProfileActivity.this).load(user.getCoverUrl()).into(binding.imgCover);updateMessageButton();}public void error(String e){targetProfileExists=false;updateMessageButton();Toast.makeText(ProfileActivity.this,e,Toast.LENGTH_LONG).show();}});
}
