$path="$root/ChatActivity.java";$text=[IO.File]::ReadAllText($path);$text=$text.Replace('import com.google.firebase.firestore.FirebaseFirestore;','import com.example.meetomxh.supabase.*;').Replace('private Call activeUploadCall;','private SupabaseStorage.Transfer activeUploadCall;').Replace('ActivityResultContracts.PickVisualMedia.ImageOnly.INSTANCE','ActivityResultContracts.PickVisualMedia.ImageAndVideo.INSTANCE');$body=@"
private void findOtherParticipant(String id) {chatRepository.getChat(id,new ChatRepository.OnChatListener(){public void onSuccess(Chat chat){if(isFinishing()||binding==null)return;if("group".equals(chat.getType())){currentChatState=chat;binding.tvChatTitle.setText(chat.title);binding.tvChatTitle.setOnClickListener(v->ChatControls.show(ChatActivity.this,chat));}else for(String participant:chat.getParticipants())if(!participant.equals(currentUid)){otherUid=participant;loadOtherProfile(participant);break;}}public void onError(String e){failAndClose(e);}});}
"@;$text=Replace-Method $text 'private void findOtherParticipant(String id)' $body;$body=@"
private void loadOtherProfile(String uid) {if(uid==null)return;otherUid=uid;ProfileClient.get(uid,new Api.Callback<User>(){public void success(User user){if(binding==null||isFinishing())return;binding.tvChatTitle.setText(user.getFullName());Glide.with(ChatActivity.this).load(user.getAvatarUrl()).placeholder(R.drawable.ic_home).into(binding.ivChatAvatar);}public void error(String e){if(binding!=null)binding.tvChatTitle.setText("Người dùng không khả dụng");}});}
