$path="$root/fragments/InboxFragment.java";$text=[IO.File]::ReadAllText($path);$text=$text.Replace('import com.google.firebase.firestore.FirebaseFirestore;','import com.example.meetomxh.supabase.*;');$body=@"
private void loadProfileOnce(String uid) {if(profiles.containsKey(uid)||!profilesLoading.add(uid))return;ProfileClient.get(uid,new Api.Callback<com.example.meetomxh.models.User>(){public void success(com.example.meetomxh.models.User user){profilesLoading.remove(uid);if(binding==null)return;profiles.put(uid,new UserProfile(user.getFullName(),user.getAvatarUrl()));renderChats();}public void error(String e){profilesLoading.remove(uid);if(binding!=null){profiles.put(uid,new UserProfile("Người dùng không khả dụng",null));renderChats();}}});}
"@;$text=Replace-Method $text 'private void loadProfileOnce(String uid)' $body;$text=$text.Replace('if (chat == null || chat.getParticipants() == null || chat.getParticipants().size() != 2) return null;','if(chat!=null && "group".equals(chat.getType())) return chat.getChatId(); if (chat == null || chat.getParticipants() == null || chat.getParticipants().size() != 2) return null;');$text=$text.Replace('UserProfile profile = profiles.get(otherUid);','UserProfile profile = "group".equals(chat.getType()) ? new UserProfile(chat.title + ("archived".equals(chat.state)?" (lưu trữ)":""),null) : profiles.get(otherUid);');$text=$text.Replace('intent.putExtra(ChatActivity.EXTRA_OTHER_UID, inbox.getOtherUid());','if(!inbox.getId().equals(inbox.getOtherUid()))intent.putExtra(ChatActivity.EXTRA_OTHER_UID, inbox.getOtherUid());');[IO.File]::WriteAllText($path,$text,(New-Object Text.UTF8Encoding($false)))